-- ============================================================
-- ZOS GEOGRAPHY — France Launch Bootstrap v1
-- ============================================================
-- Source authority:
--   INSEE Code officiel géographique (COG) 2026, geography at 2026-01-01.
--   Cross-checked against geo.api.gouv.fr administrative API.
--
-- Boundary:
--   * canonical ZOS Geography only;
--   * France country root;
--   * all 18 current regions;
--   * all 101 current departments;
--   * 24 launch communes used by the initial Z Find France market;
--   * French canonical names, official INSEE codes and provenance;
--   * no zones_lite, Property, Development, Listing or publication writes;
--   * no destructive SQL;
--   * replay-safe; conflicts fail through canonical uniqueness/postconditions.
--
-- Full commune coverage is intentionally a later ingestion wave. This launch
-- bootstrap does not pretend that 24 communes represent the complete COG.
-- ============================================================

do $$
begin
  if to_regclass('zos.geography_locations') is null
     or to_regclass('zos.geography_names') is null
     or to_regclass('zos.geography_external_codes') is null
     or to_regclass('zos.geography_provenance') is null
     or to_regclass('zos.geography_location_history') is null then
    raise exception 'France Geography bootstrap requires canonical ZOS Geography tables';
  end if;

  if exists (
    select 1
    from zos.geography_locations
    where country_iso = 'FR'
      and location_type = 'country'
      and status = 'active'
      and canonical_code <> 'FR'
  ) then
    raise exception 'France Geography conflict: unexpected active FR country root';
  end if;
end
$$;

insert into zos.geography_locations (location_type, canonical_code, country_iso, parent_id, status, valid_from)
select 'country', 'FR', 'FR', null, 'active', '2026-01-01'::timestamptz
where not exists (select 1 from zos.geography_locations where country_iso='FR' and location_type='country' and canonical_code='FR' and status='active');

with desired(region_code, official_name) as (
  values
    ('11', 'Île-de-France'),
    ('24', 'Centre-Val de Loire'),
    ('27', 'Bourgogne-Franche-Comté'),
    ('28', 'Normandie'),
    ('32', 'Hauts-de-France'),
    ('44', 'Grand Est'),
    ('52', 'Pays de la Loire'),
    ('53', 'Bretagne'),
    ('75', 'Nouvelle-Aquitaine'),
    ('76', 'Occitanie'),
    ('84', 'Auvergne-Rhône-Alpes'),
    ('93', 'Provence-Alpes-Côte d''Azur'),
    ('94', 'Corse'),
    ('01', 'Guadeloupe'),
    ('02', 'Martinique'),
    ('03', 'Guyane'),
    ('04', 'La Réunion'),
    ('06', 'Mayotte')
), fr_root as (
  select id from zos.geography_locations where country_iso='FR' and location_type='country' and canonical_code='FR' and status='active'
)
insert into zos.geography_locations (location_type, canonical_code, country_iso, parent_id, status, valid_from)
select 'region','FR-REG-' || d.region_code,'FR',r.id,'active','2026-01-01'::timestamptz
from desired d cross join fr_root r
where not exists (select 1 from zos.geography_locations gl where gl.country_iso='FR' and gl.location_type='region' and gl.canonical_code='FR-REG-' || d.region_code and gl.status='active');

