insert into zos.geography_names (location_id, language_code, name, name_type, valid_from)
select gl.id,'fr',d.official_name,'canonical','2026-01-01'::timestamptz
from desired d join zos.geography_locations gl on gl.country_iso='FR' and gl.location_type=d.location_type and gl.canonical_code=d.canonical_code and gl.status='active'
where not exists (select 1 from zos.geography_names gn where gn.location_id=gl.id and gn.language_code='fr' and gn.name_type='canonical' and gn.valid_to is null);

