insert into zos.geography_provenance (location_id, source_code, source_record_id, source_version, batch_id, observed_at, raw_payload)
select gl.id,'INSEE_COG',d.source_record_id,'2026-01-01','zfind-france-geography-inventory-v1',now(),jsonb_build_object('location_type',d.location_type,'canonical_code',d.canonical_code,'official_name',d.official_name)
from desired d join zos.geography_locations gl on gl.country_iso='FR' and gl.location_type=d.location_type and gl.canonical_code=d.canonical_code and gl.status='active'
where not exists (select 1 from zos.geography_provenance gp where gp.location_id=gl.id and gp.source_code='INSEE_COG' and gp.source_record_id=d.source_record_id and gp.source_version='2026-01-01');

insert into zos.geography_location_history (location_id, change_type, before_state, after_state, provenance_id, batch_id, changed_by)
select gp.location_id,'confirmed',null,jsonb_build_object('country_iso','FR','source','INSEE_COG','source_version','2026-01-01'),gp.id,'zfind-france-geography-inventory-v1','migration'
from zos.geography_provenance gp
where gp.source_code='INSEE_COG' and gp.source_version='2026-01-01' and gp.batch_id='zfind-france-geography-inventory-v1'
  and not exists (select 1 from zos.geography_location_history gh where gh.location_id=gp.location_id and gh.change_type='confirmed' and gh.batch_id='zfind-france-geography-inventory-v1');

do $$
declare region_count integer; department_count integer; commune_count integer;
begin
  if (select count(*) from zos.geography_locations where country_iso='FR' and location_type='country' and canonical_code='FR' and status='active') <> 1 then raise exception 'France Geography postcondition failed: country root'; end if;
  select count(*) into region_count from zos.geography_locations where country_iso='FR' and location_type='region' and canonical_code like 'FR-REG-%' and status='active';
  if region_count <> 18 then raise exception 'France Geography postcondition failed: expected 18 regions, got %', region_count; end if;
  select count(*) into department_count from zos.geography_locations where country_iso='FR' and location_type='department' and canonical_code like 'FR-DEP-%' and status='active';
  if department_count <> 101 then raise exception 'France Geography postcondition failed: expected 101 departments, got %', department_count; end if;
  select count(*) into commune_count from zos.geography_locations where country_iso='FR' and location_type='commune' and canonical_code in ('FR-COM-75056','FR-COM-45234','FR-COM-21231','FR-COM-76540','FR-COM-59350','FR-COM-67482','FR-COM-44109','FR-COM-35238','FR-COM-33063','FR-COM-31555','FR-COM-69123','FR-COM-13055','FR-COM-2A004','FR-COM-97101','FR-COM-97209','FR-COM-97302','FR-COM-97411','FR-COM-97611','FR-COM-06088','FR-COM-06029','FR-COM-34172','FR-COM-74010','FR-COM-13001','FR-COM-78646') and status='active';
  if commune_count <> 24 then raise exception 'France Geography postcondition failed: expected 24 launch communes, got %', commune_count; end if;
  if exists (select 1 from zos.geography_locations child join zos.geography_locations parent on parent.id=child.parent_id where child.country_iso='FR' and child.location_type in ('region','department','commune') and child.status='active' and parent.country_iso <> 'FR') then raise exception 'France Geography postcondition failed: cross-country parent leakage'; end if;
end
$$;